/* Hero variant switch, for A/B comparison.
 *
 *   /?hero=css        the CSS-animated still (current default)
 *   /?hero=kling      video generated by Kling 2.1 Pro
 *   /?hero=seedance   video generated by Seedance 1.0 Pro
 *   /?hero=hailuo     video generated by Hailuo 02 Pro
 *
 * With any hero= present, a small switcher appears bottom-left so you can flip
 * between them in place. With no parameter the page is untouched.
 */
(function () {
  "use strict";
  var VIDEOS = ["kling", "seedance", "hailuo"];
  var want = new URLSearchParams(location.search).get("hero");
  if (!want && !document.querySelector(".abcard video")) return;

  var ghoul = document.querySelector(".ghoul");
  if (ghoul && VIDEOS.indexOf(want) !== -1) {
    var v = document.createElement("video");
    v.className = "ghoul-video";
    v.muted = true; v.loop = true; v.autoplay = true; v.playsInline = true;
    v.setAttribute("muted", ""); v.setAttribute("playsinline", ""); v.setAttribute("loop", "");
    v.preload = "auto";
    v.poster = "/assets/hero/hero_" + want + "_poster.jpg";
    v.src = "/assets/hero/hero_" + want + ".mp4";
    ghoul.classList.add("has-video");
    ghoul.insertBefore(v, ghoul.firstChild);
    kick(v);
  }

  // Also nudge any comparison-page videos.
  Array.prototype.forEach.call(document.querySelectorAll(".abcard video"), kick);

  // Muted autoplay is allowed almost everywhere, but a few cases (iOS Low Power
  // Mode, some data-saver settings) hold the first play until the user does
  // anything. Retry on the first interaction and whenever the tab returns.
  function kick(el) {
    function tryPlay() { var p = el.play(); if (p && p.catch) p.catch(function () {}); }
    tryPlay();
    var once = function () { tryPlay(); ["pointerdown","touchstart","keydown","scroll"].forEach(function (e) { window.removeEventListener(e, once); }); };
    ["pointerdown","touchstart","keydown","scroll"].forEach(function (e) { window.addEventListener(e, once, { passive: true }); });
    document.addEventListener("visibilitychange", function () { if (!document.hidden) tryPlay(); });
  }

  if (!want) return;
  var bar = document.createElement("div");
  bar.className = "hero-switch mono";
  var names = ["css"].concat(VIDEOS);
  bar.innerHTML = "HERO:&nbsp;" + names.map(function (n) {
    return '<a href="/?hero=' + n + '"' + (n === want ? ' class="on"' : "") + ">" + n + "</a>";
  }).join("") + '<a href="/ab/">compare &rarr;</a>';
  document.body.appendChild(bar);
})();
